const b = $input.first().json.body || {};
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const campos = Array.isArray(b.campos) ? b.campos : Object.entries(b.datos || {});
const filas = campos.map(([l, v]) => `<tr><td style="padding:6px 12px 6px 0;color:#5b5b5b;vertical-align:top"><b>${esc(l)}</b></td><td style="padding:6px 0">${esc(v).replace(/\n/g, '<br>')}</td></tr>`).join('');
const fecha = new Date(b.fecha || Date.now()).toLocaleString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires' });
const html = `<div style="font-family:Arial,sans-serif;font-size:15px;color:#202020"><p style="background:#F3DA00;padding:12px 16px;border-radius:8px;font-weight:bold;margin:0 0 16px">${esc(b.asunto || 'Nuevo formulario en la web')}</p><table style="border-collapse:collapse">${filas}</table><p style="color:#5b5b5b;font-size:13px;margin-top:20px">Formulario: ${esc(b.tipo)} · ${esc(fecha)}<br>Desde: ${esc(b.origen)}</p></div>`;
return [{ json: { asunto: `[Web SNFM] ${b.asunto || 'Nuevo formulario'}${b.datos && b.datos.nombre ? ' · ' + b.datos.nombre : ''}`, html, replyTo: (b.datos && b.datos.email) || '' } }];
